CREATE OR REPLACE FUNCTION "public"."log_event_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_action text;
begin
  -- Fallback action jika NULL
  v_action := coalesce(new.action, new.status, 'approval');

  insert into public.activity_logs (
    actor_id,
    entity,
    entity_id,
    action,
    metadata,
    created_at
  )
  values (
    new.approved_by,
    'event',
    new.event_id,
    v_action,
    jsonb_build_object(
      'status', new.status,
      'notes', new.notes
    ),
    now()
  );

  return new;
end;
$$;

